OPJ_BOOL read_and_decode_rle4_bitmap(FILE *IN, OPJ_UINT8 *pData, OPJ_UINT32 stride, OPJ_UINT32 width, OPJ_UINT32 height) {
    OPJ_UINT32 expected_pixel_count = width * height;
    OPJ_UINT32 pixel_count = 0;
    OPJ_UINT32 y;
    OPJ_UINT8 *row_ptr;
    OPJ_UINT8 byte;

    for (y = 0; y < height; y++) {
        row_ptr = pData + y * stride;

        while (pixel_count < expected_pixel_count) {
            if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
                return OPJ_FALSE;
            }

            if (byte == 0) {
                // End of line or packet marker
                break;
            }

            OPJ_UINT8 count = byte & 0x0F;
            OPJ_UINT8 value = (byte & 0xF0) >> 4;

            if (count == 0) {
                // End of line or end of packet
                break;
            }

            OPJ_UINT32 i;
            for (i = 0; i < count; i++) {
                if (pixel_count >= expected_pixel_count) {
                    return OPJ_FALSE;
                }
                row_ptr[pixel_count % width] = value;
                pixel_count++;
            }
        }

        if (pixel_count < (y + 1) * width) {
            return OPJ_FALSE;
        }
    }

    if (pixel_count != expected_pixel_count) {
        // Issue a warning here if the number of pixels doesn't match
        return OPJ_FALSE;
    }

    return OPJ_TRUE;
}

