                // End of picture
                if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
                    return OPJ_FALSE;
                }
                if (byte != 0x00) {
                    // Invalid end of picture byte
                    return OPJ_FALSE;
