                    return OPJ_FALSE;
                }
                // Skip delta command for now
            } else if (byte == 0x00) {
                // Absolute mode
                absolute_mode = OPJ_TRUE;
                encoded_mode = OPJ_FALSE;
            } else {
                // Encoded mode
                encoded_mode = OPJ_TRUE;
                absolute_mode = OPJ_FALSE;

                for (i = 0; i < (byte * 2); ++i) {
                    if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
                        return OPJ_FALSE;
                    }
                    pixel = (byte >> 4) & 0x0F;
                    if (col < width) {
                        pDest[col] = pixel;
                        ++col;
                        ++actual_pixel_count;
                    }

                    pixel = byte & 0x0F;
                    if (col < width) {
                        pDest[col] = pixel;
                        ++col;
                        ++actual_pixel_count;
                    }
                }
            }

            if (absolute_mode) {
