OPJ_BOOL read_and_decode_rle4_bitmap(FILE *IN, OPJ_UINT8 *pData, OPJ_UINT32 stride, OPJ_UINT32 width, OPJ_UINT32 height) {
    OPJ_UINT32 row = 0;
    OPJ_UINT32 col = 0;
    OPJ_UINT32 expected_pixels = width * height;
    OPJ_UINT32 written_pixels = 0;
    OPJ_UINT8 *row_ptr = pData;
    OPJ_UINT8 byte;
    OPJ_BOOL success = OPJ_TRUE;

    while (row < height && success) {
        OPJ_UINT8 *pixel_ptr = row_ptr;
        OPJ_UINT32 remaining = width - col;
        OPJ_UINT32 read_pixels = 0;

        while (read_pixels < remaining && !feof(IN) && success) {
            if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
                success = OPJ_FALSE;
                break;
            }

            if (byte == 0x01) {
                // End of line
                col = 0;
                break;
            } else if (byte == 0x02) {
                // End of block
                read_pixels = remaining;
            } else if (byte == 0x03) {
                // Delta command
                OPJ_UINT8 dx = 0;
                OPJ_UINT8 dy = 0;
                if (fread(&dx, sizeof(OPJ_UINT8), 1, IN) != 1 || fread(&dy, sizeof(OPJ_UINT8), 1, IN) != 1) {
                    success = OPJ_FALSE;
                    break;
                }
                col += dx;
                row += dy;
                row_ptr = pData + row * stride;
                pixel_ptr = row_ptr + col;
            } else {
                // Pixel data
                OPJ_UINT8 pixel_data;
                if (fread(&pixel_data, sizeof(OPJ_UINT8), 1, IN) != 1) {
                    success = OPJ_FALSE;
                    break;
                }
                if (pixel_ptr + 1 > row_ptr + stride) {
                    success = OPJ_FALSE;
                    break;
                }
                *pixel_ptr++ = pixel_data;
                col++;
                read_pixels++;
                written_pixels++;
            }
        }

        if (col == width) {
            row++;
            col = 0;
            row_ptr += stride;
        }
    }

    if (written_pixels != expected_pixels) {
        // Handle warning, e.g., log or print a message
        // For example:
        // fprintf(stderr, "Warning: Number of written pixels (%u) does not match expected (%u)\n", written_pixels, expected_pixels);
    }

    return success;
}

