    OPJ_UINT32 expected_pixel_count = width * height;
    OPJ_UINT32 actual_pixel_count = 0;
    OPJ_UINT32 row = height;
    OPJ_UINT32 col = 0;
    OPJ_UINT32 bytes_per_pixel = 4; // RLE4 uses 4 pixels per byte

    while (row > 0) {
        OPJ_UINT8 byte;
        if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
            return OPJ_FALSE;
        }

        if ((byte & 0x80) != 0) {
            // Encoded mode
            OPJ_UINT8 count = (byte & 0x7F) + 1;
            OPJ_UINT8 pixel = (byte >> 4) & 0x0F;
            for (OPJ_UINT32 i = 0; i < count; ++i) {
                if (col + 1 > width) {
                    return OPJ_FALSE;
                }
                pData[(height - row) * stride + col / bytes_per_pixel] |= (pixel << ((col % bytes_per_pixel) * 4));
                ++col;
                ++actual_pixel_count;
            }
        } else {
            // Absolute mode
            OPJ_UINT8 count = (byte & 0x7F) + 1;
            for (OPJ_UINT32 i = 0; i < count; ++i) {
                OPJ_UINT8 pixel;
                if (fread(&pixel, sizeof(OPJ_UINT8), 1, IN) != 1) {
                    return OPJ_FALSE;
                }
                if (col + 1 > width) {
                    return OPJ_FALSE;
                }
                pData[(height - row) * stride + col / bytes_per_pixel] |= (pixel << ((col % bytes_per_pixel) * 4));
