OPJ_BOOL read_and_decode_rle4_bitmap(FILE* IN, OPJ_UINT8* pData, OPJ_UINT32 stride, OPJ_UINT32 width, OPJ_UINT32 height) {
    OPJ_UINT32 expected_pixel_count = width * height;
    OPJ_UINT32 actual_pixel_count = 0;
    OPJ_UINT32 x = 0, y = 0;

    while (actual_pixel_count < expected_pixel_count && !feof(IN)) {
        OPJ_UINT8 byte;
        if (fread(&byte, 1, 1, IN) != 1) {
            return OPJ_FALSE;
        }

        switch (byte) {
            case 0x00: {
                // End-of-line marker
                if (x != width) {
                    return OPJ_FALSE;
                }
                x = 0;
                y++;
                break;
            }
            case 0xFF: {
                // End-of-packet marker (unused in RLE4 for bitmaps)
                continue;
            }
            default: {
                // Pixel run (encoded mode)
                OPJ_UINT8 high_nibble = (byte & 0xF0) >> 4;
                OPJ_UINT8 low_nibble = byte & 0x0F;

                for (int i = 0; i < 2; i++) {
                    OPJ_UINT8 pixel = (i == 0) ? high_nibble : low_nibble;
                    if (x >= width) {
                        return OPJ_FALSE;
                    }
                    pData[y * stride + x++] = pixel;
                    actual_pixel_count++;
                }
                break;
            }
        }

        if (y >= height) {
            break;
        }
    }

    if (actual_pixel_count != expected_pixel_count) {
        // Warning: Pixel count mismatch
        return OPJ_FALSE;
    }

    return OPJ_TRUE;
}
